import json
import itertools

def solve_puzzle():
    # Define the puzzle parameters
    houses = [1, 2]  # House numbers from left (1) to right (2)
    names = ["Arnold", "Eric"]
    birthdays = ["april", "sept"]
    mothers = ["Aniya", "Holly"]

    solutions = []

    # Iterate over all possible assignments (permutations) for each category
    for name_perm in itertools.permutations(names, len(houses)):
        names_by_house = {house: name_perm[i] for i, house in enumerate(houses)}

        for bday_perm in itertools.permutations(birthdays, len(houses)):
            bdays_by_house = {house: bday_perm[i] for i, house in enumerate(houses)}

            # Clue 2: The person whose birthday is in April is in the first house.
            if bdays_by_house[1] != "april":
                continue

            for mother_perm in itertools.permutations(mothers, len(houses)):
                mothers_by_house = {house: mother_perm[i] for i, house in enumerate(houses)}

                # Helper functions to find house indices by attribute
                def house_of_name(target_name):
                    for h in houses:
                        if names_by_house[h] == target_name:
                            return h
                    return None

                def house_of_mother(target_mother):
                    for h in houses:
                        if mothers_by_house[h] == target_mother:
                            return h
                    return None

                # Clue 1: Eric is somewhere to the left of the person whose mother's name is Holly.
                if not (house_of_name("Eric") < house_of_mother("Holly")):
                    continue

                # If all constraints satisfied, record solution
                solutions.append((names_by_house, bdays_by_house, mothers_by_house))

    # Choose the (unique) solution
    if not solutions:
        raise ValueError("No solution found for the given puzzle.")
    names_by_house, bdays_by_house, mothers_by_house = solutions[0]

    # Prepare the output rows in order of houses
    rows = []
    for house in houses:
        row = [
            str(house),
            names_by_house[house],
            bdays_by_house[house],
            mothers_by_house[house],
        ]
        rows.append(row)

    result = {
        "solution": {
            "header": ["House", "Name", "Birthday", "Mother"],
            "rows": rows,
        }
    }
    return result

if __name__ == "__main__":
    solution = solve_puzzle()
    print(json.dumps(solution, ensure_ascii=False))
